'use strict';
const publishers=['연합뉴스','연합인포맥스','매일경제','블로터','지디넷코리아'];
const state={page:location.hash.startsWith('#news/article/')?'reader':location.hash==='#news'?'news':'home',type:'news',active:new Set(publishers),draft:new Set(publishers),filterOpen:false,dataState:'sample',articleId:null,listScroll:0,listFocus:null};
if('scrollRestoration' in history)history.scrollRestoration='manual';
const e=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const svg=path=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
const icons={home:svg('<path d="M3 10 12 3l9 7v10H3z"/><path d="M9 20v-7h6v7"/>'),market:svg('<path d="M4 20V10m5 10V5m5 15v-7m5 7V3"/>'),stocks:svg('<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>'),assets:svg('<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18m-6 5h3"/>'),journal:svg('<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M3 7h4m-4 5h4m-4 5h4m4-10h5m-5 5h5"/>')};
const nav=[['home','홈'],['market','시장'],['stocks','종목'],['assets','자산관리'],['journal','일지']];
function outside(label){document.getElementById('status').textContent=`${label}: 이번 구현은 승인된 홈·뉴스공시까지만 포함합니다.`;}
function head(title,home=false){return `<header class="sb-header"><div class="sb-headrow"><h1>${home?'Stock <span>Book</span>':title}</h1>${home?'<small>표시 값 예시</small>':''}</div><div class="sb-tabs">${home?'<button type="button" aria-pressed="true">내 투자</button><button type="button" data-outside="발견">발견</button>':'<button type="button" data-outside="시황">시황</button><button type="button" aria-pressed="true">뉴스·공시</button><button type="button" data-outside="경제일정">경제일정</button>'}</div></header>`;}
function cardHeader(title,label,target){return `<div class="sb-cardhead"><h2>${title}</h2><button type="button" data-outside="${target}">${label} ›</button></div>`;}
function home(){return head('',true)+`<main class="sb-feed" aria-label="홈"><article class="sb-card sb-assets" data-card="assets">${cardHeader('총자산','상세','총자산 상세')}<div class="sb-money">13,680,000<small>원</small></div><div class="sb-breakdown"><span>보유주식<b>12,480,000원</b></span><span>예수금<b>1,200,000원</b></span></div></article><article class="sb-card" data-card="stocks">${cardHeader('보유·관심종목','전체','종목 목록')}${[['삼성전자','보유 12주 · 관심','84,000','up','▲ 1.20%'],['SK하이닉스','보유 40주 · 관심','186,000','down','▼ 0.80%'],['현대차','관심','240,000','up','▲ 0.40%']].map(([name,sub,price,direction,change])=>`<div class="sb-stockrow"><div><div class="sb-name">${name}</div><small>${sub}</small></div><div class="sb-number">${price}원<div class="sb-change sb-${direction}">${change}</div></div></div>`).join('')}</article><article class="sb-card" data-card="indices">${cardHeader('시장 지수','시장','시장 시황')}<div class="sb-indexes">${[['KOSPI','2,650.00','▲ 0.76%'],['KOSDAQ','850.00','▲ 0.59%']].map(([name,value,change])=>`<div><small>${name}</small><strong>${value}</strong><div class="sb-change sb-up">${change}</div></div>`).join('')}</div></article><article class="sb-card" data-card="signal">${cardHeader('투자 신호','종목 보기','종목 상세')}<div class="sb-signal-stock">삼성전자</div><section class="sb-signal"><strong>골든크로스 발생</strong><p>최근 5일 평균 주가가<br>10일 평균을 넘어섰어요</p></section><details><summary><span>10.16 종가 · 가상 예시</span><span>판정 근거 ＋</span></summary><p>직전에는 5일 평균이 10일 평균 아래에,<br>이번에는 위에 있어요.</p></details><small>규칙 판정 · 투자 권유 아님</small></article><article class="sb-card sb-schedule" data-card="schedule">${cardHeader('주요 일정','전체','경제일정')}<div class="sb-quick"><small>21:30</small><span class="sb-name">미국 고용 지표</span><small>일정 예시</small></div></article><article class="sb-card" data-card="draft">${cardHeader('작성 중인 투자일지','일지 보기','일지 목록')}<div class="sb-draft"><strong class="sb-name">삼성전자 · 초안</strong><p>실적 회복을 확인한 뒤 나눠서 매수하기로 했다.</p></div></article></main>`;}
function newsShell(){return head('시장')+`<main class="sb-feed" aria-label="뉴스·공시"><div class="sb-newsheader"><h2>뉴스·공시</h2><small>보관 자료 예시</small></div><div class="sb-filterbar"><div class="sb-switch" aria-label="뉴스 분류">${[['news','일반 기사'],['disclosure','공시']].map(([type,label])=>`<button type="button" data-type="${type}" aria-pressed="${state.type===type}">${label}</button>`).join('')}</div><button type="button" class="sb-filter-button" id="filter-toggle" aria-controls="publisher-filter" aria-expanded="${state.filterOpen}" ${state.type==='disclosure'?'hidden':''}>필터${state.active.size===publishers.length?'':' · '+state.active.size}</button></div><section id="publisher-filter" class="sb-filterbox" ${state.filterOpen&&state.type==='news'?'':'hidden'}><h3>언론사</h3>${publishers.map((name,i)=>`<label for="publisher-${i}"><input type="checkbox" id="publisher-${i}" data-publisher="${name}" ${state.draft.has(name)?'checked':''}>${name}</label>`).join('')}<div class="sb-filter-actions"><button type="button" id="select-all">전체 선택</button><button type="button" class="sb-primary" id="apply">적용 · ${state.draft.size}개 언론사</button></div></section><div id="news-results"></div><small>보관 기사 예시 · 기사를 누르면 프로그램 안에서 읽기<br>공시는 가상 문서 예시 · 실제 공시 연결 전</small></main>`;}
function newsResults(){const root=document.getElementById('news-results');if(!root)return;const isNews=state.type==='news',rows=referenceNews.filter(r=>state.active.has(r.media)).slice().sort((a,b)=>b.date.localeCompare(a.date));root.innerHTML=`<div class="sb-meta" role="status"><span>${isNews?'일반 기사 '+rows.length+'건':'공시 3건 · 가상 예시'}</span>${isNews?'<span>발행일 최신순</span>':''}</div>${isNews&&state.active.size!==publishers.length?`<p class="sb-selected">${state.active.size?'언론사 · '+publishers.filter(x=>state.active.has(x)).join(' · '):'선택한 언론사 없음'}</p>`:''}`;
 if(!isNews){root.insertAdjacentHTML('beforeend',[['예시 기업 A','분기보고서','정기공시'],['예시 기업 B','[기재정정] 주요사항보고서','정정'],['예시 기업 C','주요사항보고서','주요사항']].map(([company,title,kind],i)=>`<article class="sb-article sb-filing sb-article-copy"><div class="sb-filingtop"><span class="sb-publisher">${company}</span><span class="sb-tag ${kind==='정정'?'sb-tag-correction':''}">${kind}</span></div><h3>${title}</h3><small>제출일 표시 · 전자공시</small><button type="button" data-filing="${i}" aria-expanded="false" aria-controls="filing-note-${i}">원문 보기 ↗</button><p class="sb-note" id="filing-note-${i}" hidden>실제 공시 연결 전 예시입니다. 이 위치에서 해당 공시 원문을 엽니다.</p></article>`).join(''));return;}
 if(!rows.length){root.insertAdjacentHTML('beforeend','<div class="sb-empty">선택한 조건의 기사가 없습니다.<button type="button" id="reset-empty">전체 언론사 보기</button></div>');return;}
 for(const r of rows){const article=document.createElement('button');article.type='button';article.className='sb-article sb-article-button';article.dataset.article=String(referenceNews.indexOf(r));if(r.image?.startsWith('data:image/webp;base64,')){const img=document.createElement('img');img.src=r.image;img.alt=r.media+' 보관 기사 예시 사진';article.append(img);}const copy=document.createElement('div');copy.className='sb-article-copy';copy.innerHTML=`<div class="sb-publisher">${e(r.media)}</div><h3>${e(r.title)}</h3><div class="sb-caption"><time datetime="${e(r.date.replaceAll('.','-'))}">${e(r.date)}</time><span>기사 읽기 ›</span></div>`;article.append(copy);root.append(article);}}
function reader(){
 const item=referenceNews[state.articleId];
 if(!item)return '<header class="sb-header"><h1>기사 읽기</h1></header><main class="sb-feed"><section class="sb-card"><p>기사를 찾을 수 없습니다.</p><button type="button" data-reader-back>뉴스 목록으로</button></section></main>';
 const url=new URL(item.url);const original=url.protocol==='https:'?`<a class="sb-original" href="${e(url.href)}" target="_blank" rel="noopener noreferrer">언론사 원문 별도 창으로 보기 ↗</a>`:'';
 return `<header class="sb-header"><button type="button" data-reader-back>‹ 뉴스 목록</button></header><main class="sb-feed" aria-label="기사 리딩"><article class="sb-card sb-reader"><div class="sb-publisher">${e(item.media)}</div><h1 tabindex="-1">${e(item.title)}</h1><time datetime="${e(item.date.replaceAll('.','-'))}">${e(item.date)} · 보관 기사 제목 예시</time><div class="sb-note">본문 미연결 · 아래는 리딩 UI 검토용 예시 문장입니다. 실제 기사 본문이나 요약이 아닙니다.</div>${item.image?`<figure><img src="${e(item.image)}" alt="${e(item.media)} 보관 기사 예시 사진"><figcaption>디자인 원본의 보관 사진 · 실제 본문 제공과 별개</figcaption></figure>`:''}<div class="sb-reader-body"><p>이 영역은 프로그램 안에서 기사 내용을 읽는 흐름을 확인하기 위한 예시입니다.</p><p>목록에서 선택한 제목, 언론사와 발행일을 유지한 채 내용을 읽고, 뉴스 목록으로 돌아갈 수 있습니다.</p><p>실제 본문은 아직 연결되지 않았습니다. 본문과 이미지의 제공 범위, 출처 표시와 이용 조건은 별도로 확인해야 합니다.</p></div><div class="sb-reader-footer">${original}<button type="button" data-reader-back>뉴스 목록으로 돌아가기</button></div></article></main>`;
}
function render(){document.getElementById('screen').innerHTML=state.page==='home'?home():state.page==='reader'?reader():newsShell();
 if(state.dataState!=='sample'){
  const messages={unconnected:'데이터 미연결 · 아직 제공원에 연결하지 않았습니다.',loading:'데이터를 불러오는 중입니다.',error:'데이터 갱신에 실패했습니다. 실제 데이터 연결 전 검토 상태입니다.',empty:'조회 완료 · 조건에 맞는 실제 결과가 없습니다.'};
  document.querySelector('main').innerHTML='<section class="sb-card" role="status" aria-live="polite"'+(state.dataState==='loading'?' aria-busy="true"':'')+'><h2>'+messages[state.dataState]+'</h2><p class="sb-small">표시 상태 검토용입니다. 미수신 금액을 0원으로 대체하지 않습니다.</p><button type="button" id="return-sample">가상 예시로 돌아가기</button></section>';
 }document.querySelector('nav').innerHTML=nav.map(([key,label])=>`<button type="button" data-nav="${key}" ${key===(state.page==='home'?'home':'market')?'aria-current="page"':''}>${icons[key]}<span>${label}</span></button>`).join('');newsResults();}
function routeFromHash(){const match=location.hash.match(/^#news\/article\/(\d+)$/);return match?{page:'reader',articleId:Number(match[1])}:{page:location.hash==='#news'?'news':'home',articleId:null};}
function focusHeading(){const heading=document.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function navigate(page){state.filterOpen=false;history.pushState(null,'',page==='news'?'#news':'#home');state.page=page;state.articleId=null;render();document.getElementById('status').textContent='';window.scrollTo(0,0);focusHeading();}
function openArticle(id){state.listScroll=window.scrollY;state.listFocus=id;state.page='reader';state.articleId=id;history.pushState({readerFromList:true},'','#news/article/'+id);render();window.scrollTo(0,0);focusHeading();}
function restoreList(){requestAnimationFrame(()=>{const target=document.querySelector('[data-article="'+state.listFocus+'"]');if(target)target.focus({preventScroll:true});window.scrollTo(0,state.listScroll);});}
function onHistory(){const previous=state.page;Object.assign(state,routeFromHash());state.filterOpen=false;render();if(previous==='reader'&&state.page==='news')restoreList();else{window.scrollTo(0,0);focusHeading();}}
function readerBack(){if(history.state?.readerFromList){history.back();}else{history.replaceState(null,'','#news');state.page='news';state.articleId=null;render();restoreList();}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.article!==undefined){openArticle(Number(b.dataset.article));return;}if(b.hasAttribute('data-reader-back')){readerBack();return;}if(b.id==='return-sample'){state.dataState='sample';document.getElementById('data-state').value='sample';render();return;}if(b.dataset.outside){outside(b.dataset.outside);return;}if(b.dataset.nav){if(b.dataset.nav==='home')navigate('home');else if(b.dataset.nav==='market')navigate('news');else outside(nav.find(([key])=>key===b.dataset.nav)[1]);return;}if(b.dataset.type){state.type=b.dataset.type;state.filterOpen=false;render();return;}if(b.id==='filter-toggle'){state.filterOpen=!state.filterOpen;state.draft=new Set(state.active);render();document.getElementById('filter-toggle').focus();}if(b.id==='select-all'){state.draft=new Set(publishers);render();document.getElementById('select-all').focus();}if(b.id==='apply'){state.active=new Set(state.draft);state.filterOpen=false;render();document.getElementById('filter-toggle').focus();}if(b.id==='reset-empty'){state.active=new Set(publishers);state.draft=new Set(publishers);render();document.getElementById('filter-toggle').focus();}if(b.dataset.filing!==undefined){const note=document.getElementById('filing-note-'+b.dataset.filing);note.hidden=!note.hidden;b.setAttribute('aria-expanded',String(!note.hidden));}});
document.addEventListener('change',event=>{const input=event.target;if(input.dataset.publisher){input.checked?state.draft.add(input.dataset.publisher):state.draft.delete(input.dataset.publisher);document.getElementById('apply').textContent=`적용 · ${state.draft.size}개 언론사`;}if(input.id==='data-state'){state.dataState=input.value;render();}if(input.id==='text-scale')document.documentElement.style.setProperty('--sb-scale',input.value);});
window.addEventListener('popstate',onHistory);
Object.assign(state,routeFromHash());render();
